#!/usr/bin/env bash
# Prepare and start a throwaway Mirage server for the emulator end-to-end test.
#
#   1. fresh self-signed certificate valid for the emulator's view of the host
#   2. server config derived from examples/server.toml
#   3. user + access link created with the real `mirage users --add ... --link` CLI
#   4. server started (as root, it creates a TUN device) and waited for
#
# Env in:
#   E2E_DIR       work directory (cert, key, config, users file, server.log, server.pid)
#   MIRAGE_BIN    path to the mirage binary (default: <repo>/target/debug/mirage)
# Env out (via $GITHUB_ENV when set): E2E_LINK, the mirage:// access link.
#
# Certificate verification, as implemented by the client (mirage/src):
#   * TCP + camouflage "mirage": verification is OFF (camouflage/mod.rs:30 sets
#     SslVerifyMode::NONE, client/connection.rs:347 also disables hostname checks).
#   * QUIC + camouflage "mirage" (no JLS): rustls verifies the chain against the
#     embedded trusted_certificates (protocol/udp/mod.rs:53-67) and the server
#     name is camouflage.target_sni, NOT the dialed host (udp/mod.rs:372-378).
#   * camouflage "none": TCP and QUIC verify against the dialed host
#     (tcp/mod.rs:52, resolve_sni -> "10.0.2.2"), i.e. the IP SAN.
# Hence the certificate carries BOTH IP:10.0.2.2 and DNS:<target_sni>; the stock
# `--embed-cert` link then verifies on every transport in either mode and no
# test-only client setting (insecure, camouflage none) is needed.
set -euo pipefail

repo_root="$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)"
dir="${E2E_DIR:?E2E_DIR is not set}"
bin="${MIRAGE_BIN:-$repo_root/target/debug/mirage}"

host="10.0.2.2" # the host as seen from the Android emulator
port="4433"     # TCP and QUIC (UDP)
sni="www.microsoft.com" # camouflage.target_sni, same as examples/server.toml
tunnel="10.11.12.1/24"

[[ -x "$bin" ]] || { echo "::error::mirage binary not found at $bin"; exit 1; }
mkdir -p "$dir"
dir="$(cd "$dir" && pwd)"
cd "$dir"
rm -f users server.log server.pid

# 1. Certificate. basicConstraints CA:FALSE matters: the client adds this very
#    certificate as a trust anchor, and rustls-webpki rejects a CA certificate
#    that is used as the end-entity certificate. A private config file keeps the
#    result independent of the distribution's openssl.cnf.
cat >openssl.cnf <<CNF
[req]
distinguished_name = dn
prompt = no
x509_extensions = ext
[dn]
CN = mirage-e2e
[ext]
basicConstraints = critical,CA:FALSE
keyUsage = critical,digitalSignature
extendedKeyUsage = serverAuth
subjectAltName = @alt
[alt]
IP.1 = $host
DNS.1 = $sni
CNF
openssl req -x509 -newkey ec -pkeyopt ec_paramgen_curve:prime256v1 -nodes \
  -days 30 -config openssl.cnf -keyout server_key.pem -out server_cert.pem
chmod 600 server_key.pem
openssl x509 -in server_cert.pem -noout -subject -dates -ext subjectAltName,basicConstraints

# 2. Server config (mirrors examples/server.toml; IPv4 only, no post_up hooks).
cat >server.toml <<TOML
name = "mirage-e2e"
certificate_file = "$dir/server_cert.pem"
certificate_key_file = "$dir/server_key.pem"
bind_address = "0.0.0.0"
bind_port = $port
quic_enabled = true
quic_bind_port = $port
tunnel_network = "$tunnel"
isolate_clients = true

[authentication]
users_file = "$dir/users"

[connection]
mtu = 1280
outer_mtu = 1420
tcp_nodelay = true
timeout_s = 30

[obfuscation]
enabled = true
padding_probability = 0.15
padding_min = 40
padding_max = 1200
jitter_min_ms = 0
jitter_max_ms = 0

[camouflage]
mode = "mirage"
target_sni = "$sni"
short_ids = ["abcd1234deadbeef", "0011223344556677"]

[log]
level = "info,mirage=debug"
TOML

# 3. User and access link, generated by the real CLI.
password="$(openssl rand -hex 12)"
out="$("$bin" users --add "$dir/users" \
  --username e2e --password "$password" \
  --link --name e2e --host "$host" --port "$port" \
  --server-config "$dir/server.toml" --embed-cert \
  --routes 10.11.12.0/24 --dns 1.1.1.1)"
link="$(grep -m1 '^mirage://' <<<"$out" || true)"
if [[ -z "$link" ]]; then
  echo "$out"
  echo "::error::'mirage users --link' did not print a mirage:// link"
  exit 1
fi
echo "Access link: $link"
if [[ -n "${GITHUB_ENV:-}" ]]; then
  echo "E2E_LINK=$link" >>"$GITHUB_ENV"
fi

# 4. Start the server (root is needed to create the TUN device).
nohup sudo "$bin" server --config "$dir/server.toml" >"$dir/server.log" 2>&1 </dev/null &
pid=$!
echo "$pid" >"$dir/server.pid"

ready=false
for _ in $(seq 1 60); do
  if ss -H -ltn "sport = :$port" | grep -q . && ss -H -lun "sport = :$port" | grep -q .; then
    ready=true
    break
  fi
  [[ -d "/proc/$pid" ]] || break # the server exited
  sleep 0.5
done

if [[ "$ready" != true ]]; then
  echo "::error::server is not listening on $port/tcp and $port/udp after 30 s"
  echo "----- server.log"
  cat "$dir/server.log"
  echo "----- listening sockets"
  ss -H -ltnu || true
  exit 1
fi
echo "Server is listening on $port/tcp and $port/udp (log: $dir/server.log)"
ss -H -ltnu "sport = :$port"
